/* DAWAH X — ahmad, অধ্যায় 43 · খণ্ড 43 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][43]=[[8401,8401,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عُقَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْتَصُّ ‏ ‏الْخَلْقُ بَعْضُهُمْ مِنْ بَعْضٍ حَتَّى ‏ ‏الْجَمَّاءُ ‏ ‏مِنْ ‏ ‏الْقَرْنَاءِ ‏ ‏وَحَتَّى الذَّرَّةُ مِنْ الذَّرَّةِ ‏","","",""],[8402,8402,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الصَّلْتِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى السَّمَاءِ السَّابِعَةِ فَنَظَرْتُ فَإِذَا أَنَا فَوْقِي بِرَعْدٍ وَصَوَاعِقَ ثُمَّ أَتَيْتُ عَلَى قَوْمٍ بُطُونُهُمْ كَالْبُيُوتِ فِيهَا الْحَيَّاتُ تُرَى مِنْ خَارِجِ بُطُونِهِمْ فَقُلْتُ مَنْ هَؤُلَاءِ قَالَ هَؤُلَاءِ أَكَلَةُ الرِّبَا فَلَمَّا نَزَلْتُ وَانْتَهَيْتُ إِلَى سَمَاءِ الدُّنْيَا فَإِذَا أَنَا ‏ ‏بِرَهْجٍ ‏ ‏وَدُخَانٍ وَأَصْوَاتٍ فَقُلْتُ مَنْ هَؤُلَاءِ قَالَ الشَّيَاطِينُ يَحْرِفُونَ عَلَى أَعْيُنِ بَنِي ‏ ‏آدَمَ ‏ ‏أَنْ لَا يَتَفَكَّرُوا فِي مَلَكُوتِ السَّمَاوَاتِ وَالْأَرْضِ وَلَوْلَا ذَلِكَ لَرَأَتْ الْعَجَائِبَ ‏","","",""],[8403,8403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْقِنْطَارُ اثْنَا عَشَرَ أَلْفَ ‏ ‏أُوقِيَّةٍ ‏ ‏كُلُّ ‏ ‏أُوقِيَّةٍ ‏ ‏خَيْرٌ مِمَّا بَيْنَ السَّمَاءِ إِلَى الْأَرْضِ ‏","","",""],[8404,8404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ رَاشِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُبَاعَ الثَّمَرَةُ حَتَّى ‏ ‏يَبْدُوَ صَلَاحُهَا ‏","","",""],[8405,8405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَكَمِ قَائِدُ سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْأَصَمُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبِعَ جَنَازَةً قَالَ ‏ ‏انْبَسِطُوا بِهَا وَلَا تَدِبُّوا دَبِيبَ ‏ ‏الْيَهُودِ ‏ ‏بِجَنَائِزِهَا ‏","","",""],[8406,8406,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو مَرْيَمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُلْكُ فِي ‏ ‏قُرَيْشٍ ‏ ‏وَالْقَضَاءُ فِي ‏ ‏الْأَنْصَارِ ‏ ‏وَالْأَذَانُ فِي ‏ ‏الْحَبَشَةِ ‏ ‏وَالسُّرْعَةُ ‏ ‏فِي ‏ ‏الْيَمَنِ ‏ ‏وَقَالَ ‏ ‏زَيْدٌ ‏ ‏مَرَّةً يَحْفَظُهُ وَالْأَمَانَةُ فِي ‏ ‏الْأَزْدِ ‏","","",""],[8407,8407,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ مَرَّتَيْنِ مَرَّتَيْنِ ‏","","",""],[8408,8408,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي رَأَيْتُ رَأْسِي ضُرِبَ فَرَأَيْتُهُ ‏ ‏يَتَدَهْدَهُ ‏ ‏فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏يَطْرُقُ أَحَدَكُمْ الشَّيْطَانُ فَيَتَهَوَّلُ لَهُ ثُمَّ ‏ ‏يَغْدُو ‏ ‏يُخْبِرُ النَّاسَ ‏","","",""],[8409,8409,"","","‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ حَرْبٍ أَبُو صَالِحٍ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعْتُمْ ‏ ‏نُهَاقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ مِنْ شَرِّهَا فَإِنَّهَا رَأَتْ شَيْطَانًا وَإِذَا سَمِعْتُمْ صُرَاخَ الدِّيَكَةِ بِاللَّيْلِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ فَإِنَّهَا رَأَتْ مَلَكًا ‏","","",""],[8410,8410,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْمُهَزِّمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَاسْتَقْبَلَنَا ‏ ‏رِجْلٌ ‏ ‏مِنْ جَرَادٍ فَجَعَلْنَا نَضْرِبُهُنَّ بِعِصِيِّنَا وَسِيَاطِنَا فَسُقِطَ فِي أَيْدِينَا وَقُلْنَا مَا صَنَعْنَا وَنَحْنُ مُحْرِمُونَ فَسَأَلْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏لَا بَأْسَ بِصَيْدِ الْبَحْرِ ‏","","",""],[8411,8411,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ أُذَيْنٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ الْعَبْدُ الْإِيمَانَ كُلَّهُ حَتَّى يَتْرُكَ الْكَذِبَ فِي الْمُزَاحِ ‏ ‏وَالْمِرَاءَ ‏ ‏وَإِنْ كَانَ صَادِقًا ‏","","",""],[8412,8412,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ الضَّبِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏خَوْلَةَ بِنْتَ يَسَارٍ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ لَيْسَ لِي إِلَّا ثَوْبٌ وَاحِدٌ وَأَنَا أَحِيضُ فِيهِ قَالَ ‏ ‏فَإِذَا طَهُرْتِ فَاغْسِلِي مَوْضِعَ الدَّمِ ثُمَّ صَلِّي فِيهِ قَالَتْ يَا رَسُولَ اللَّهِ إِنْ لَمْ يَخْرُجْ أَثَرُهُ قَالَ يَكْفِيكِ الْمَاءُ وَلَا يَضُرُّكِ أَثَرُهُ ‏","","",""],[8413,8413,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ الْمَدِينِيُّ ‏ ‏وَذَلِكَ قَبْلَ الْمِحْنَةِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَلَمْ يُحَدِّثْ أَبِي عَنْهُ بَعْدَ الْمِحْنَةِ بِشَيْءٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ يَعْنِي الثَّقَفِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[8414,8414,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الْمَيِّتَ تَحْضُرُهُ الْمَلَائِكَةُ فَإِذَا كَانَ الرَّجُلُ الصَّالِحُ قَالُوا اخْرُجِي أَيَّتُهَا النَّفْسُ الطَّيِّبَةُ كَانَتْ فِي الْجَسَدِ الطَّيِّبِ اخْرُجِي حَمِيدَةً وَأَبْشِرِي بِرَوْحٍ وَرَيْحَانٍ وَرَبٍّ غَيْرِ غَضْبَانَ قَالَ فَلَا يَزَالُ يُقَالُ ذَلِكَ حَتَّى تَخْرُجَ ثُمَّ ‏ ‏يُعْرَجَ ‏ ‏بِهَا إِلَى السَّمَاءِ فَيُسْتَفْتَحُ لَهَا فَيُقَالُ مَنْ هَذَا فَيُقَالُ فُلَانٌ فَيَقُولُونَ مَرْحَبًا بِالنَّفْسِ الطَّيِّبَةِ كَانَتْ فِي الْجَسَدِ الطَّيِّبِ ادْخُلِي حَمِيدَةً وَأَبْشِرِي بِرَوْحٍ وَرَيْحَانٍ وَرَبٍّ غَيْرِ غَضْبَانَ قَالَ فَلَا يَزَالُ يُقَالُ لَهَا حَتَّى ‏ ‏يُنْتَهَى بِهَا إِلَى السَّمَاءِ الَّتِي فِيهَا اللَّهُ عَزَّ وَجَلَّ وَإِذَا كَانَ الرَّجُلُ السَّوْءُ قَالُوا اخْرُجِي أَيَّتُهَا النَّفْسُ الْخَبِيثَةُ كَانَتْ فِي الْجَسَدِ الْخَبِيثِ اخْرُجِي ذَمِيمَةً وَأَبْشِرِي بِحَمِيمٍ وَغَسَّاقٍ وَآخَرَ مِنْ شَكْلِهِ أَزْوَاجٍ فَلَا يَزَالُ حَتَّى تَخْرُجَ ثُمَّ ‏ ‏يُعْرَجَ ‏ ‏بِهَا إِلَى السَّمَاءِ فَيُسْتَفْتَحُ لَهَا فَيُقَالُ مَنْ هَذَا فَيُقَالُ فُلَانٌ فَيُقَالُ لَا مَرْحَبًا بِالنَّفْسِ الْخَبِيثَةِ كَانَتْ فِي الْجَسَدِ الْخَبِيثِ ارْجِعِي ذَمِيمَةً فَإِنَّهُ لَا يُفْتَحُ ‏ ‏لَكِ أَبْوَابُ السَّمَاءِ فَتُرْسَلُ مِنْ السَّمَاءِ ثُمَّ تَصِيرُ إِلَى الْقَبْرِ فَيُجْلَسُ الرَّجُلُ الصَّالِحُ فَيُقَالُ لَهُ مِثْلُ مَا قِيلَ لَهُ فِي الْحَدِيثِ الْأَوَّلِ وَيُجْلَسُ الرَّجُلُ السَّوْءُ فَيُقَالُ لَهُ مِثْلُ مَا قِيلَ فِي الْحَدِيثِ الْأَوَّلِ ‏","","",""],[8415,8415,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلُّوا عَلَيَّ فَإِنَّهَا زَكَاةٌ لَكُمْ وَاسْأَلُوا اللَّهَ لِي الْوَسِيلَةَ فَإِنَّهَا دَرَجَةٌ فِي أَعَلَى الْجَنَّةِ لَا يَنَالُهَا إِلَّا رَجُلٌ وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ ‏","","",""],[8416,8416,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رِوَايَةً ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَاهُنَا مَا ‏ ‏يَخْفَى عَلَيَّ شَيْءٌ مِنْ خُشُوعِكُمْ وَرُكُوعِكُمْ ‏","","",""],[8417,8417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَوْبَرِ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ أَنْتَ الَّذِي ‏ ‏تَنْهَى النَّاسَ أَنْ يُصَلُّوا وَعَلَيْهِمْ نِعَالُهُمْ قَالَ لَا وَلَكِنْ وَرَبِّ هَذِهِ الْحُرْمَةِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَى هَذَا ‏ ‏الْمَقَامِ ‏ ‏وَعَلَيْهِ نَعْلَاهُ وَانْصَرَفَ وَهُمَا عَلَيْهِ وَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صِيَامِ يَوْمِ الْجُمُعَةِ إِلَّا أَنْ يَكُونَ فِي أَيَّامٍ ‏","","",""],[8418,8418,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏الْمَعْنَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏مَوْلَى أَبِي رُهْمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا امْرَأَةٍ تَطَيَّبَتْ لِلْمَسْجِدِ لَمْ يُقْبَلْ لَهَا صَلَاةٌ حَتَّى تَغْسِلَهُ عَنْهَا اغْتِسَالَهَا مِنْ الْجَنَابَةِ ‏","","",""],[8419,8419,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ يَعْنِي ابْنَ خَالِدٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَرَمُ الرَّجُلِ دِينُهُ وَمُرُوءَتُهُ عَقْلُهُ وَحَسَبُهُ خُلُقُهُ ‏","","",""],[8420,8420,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ مِنْ ‏ ‏خُرَاسَانَ ‏ ‏رَايَاتٌ سُودٌ لَا يَرُدُّهَا شَيْءٌ حَتَّى تُنْصَبَ ‏ ‏بِإِيلِيَاءَ ‏","","",""],[8421,8421,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنِي ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي نَعِيمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏جَلِيسِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ وَمَنْ أُفْتِيَ بِفُتْيَا بِغَيْرِ عِلْمٍ كَانَ إِثْمُ ذَلِكَ عَلَى مَنْ أَفْتَاهُ وَمَنْ اسْتَشَارَ أَخَاهُ فَأَشَارَ عَلَيْهِ بِأَمْرٍ وَهُوَ يَرَى الرُّشْدَ غَيْرَ ذَلِكَ فَقَدْ خَانَهُ ‏","","",""],[8422,8422,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ أَبُو سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدٍ الْأَخْنَسِيِّ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جُعِلَ قَاضِيًا بَيْنَ النَّاسِ فَقَدْ ذُبِحَ بِغَيْرِ سِكِّينٍ ‏ ‏و حَدَّثَنَا ‏ ‏بَعْدَ ذَلِكَ ‏ ‏يَعْنِي ‏ ‏الْخُزَاعِيَّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏وَالْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏","","",""],[8423,8423,"","","‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جُزُّوا ‏ ‏الشَّوَارِبَ وَاعْفُوا اللِّحَى ‏","","",""],[8424,8424,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبَّادٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْأَرْبَعِ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دُعَاءٍ لَا يُسْمَعُ ‏","","",""],[8425,8425,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُجِيرُ ‏ ‏عَلَى أُمَّتِي ‏ ‏أَدْنَاهُمْ ‏","","",""],[8426,8426,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ بِلَالٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ سَلْمَانَ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يَنْبَغِي لِذِي الْوَجْهَيْنِ أَنْ يَكُونَ أَمِينًا ‏","","",""],[8427,8427,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْبَغِي لِلصَّدِيقِ أَنْ يَكُونَ ‏ ‏لَعَّانًا ‏","","",""],[8428,8428,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَرَسُ مِزْمَارُ الشَّيْطَانِ ‏","","",""],[8429,8429,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصُّلْحُ ‏ ‏جَائِزٌ ‏ ‏بَيْنَ الْمُسْلِمِينَ ‏","","",""],[8430,8430,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جُزُّوا ‏ ‏الشَّوَارِبَ وَاعْفُوا اللِّحَى وَخَالِفُوا ‏ ‏الْمَجُوسَ ‏","","",""],[8431,8431,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ الْبَصَرُ فَلَا إِذْنَ ‏","","",""],[8432,8432,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ ‏ ‏عَمْرَو بْنَ عَامِرٍ ‏ ‏يَجُرُّ ‏ ‏قُصْبَهُ ‏ ‏فِي النَّارِ وَكَانَ أَوَّلَ مَنْ ‏ ‏سَيَّبَ ‏ ‏السَّائِبَةَ وَبَحَرَ ‏ ‏الْبَحِيرَةَ ‏","","",""],[8433,8433,"","","‏ ‏حَدَّثَنَا ‏ ‏الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[8434,8434,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏كُلَّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏ ‏وَالْمُجَثَّمَةَ ‏ ‏وَالْحِمَارَ الْإِنْسِيَّ ‏","","",""],[8435,8435,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَنْفَقَ زَوْجًا ‏ ‏أَوْ قَالَ زَوْجَيْنِ ‏ ‏مِنْ مَالِهِ ‏ ‏أُرَاهُ قَالَ فِي سَبِيلِ اللَّهِ ‏ ‏دَعَتْهُ خَزَنَةُ الْجَنَّةِ يَا مُسْلِمُ هَذَا خَيْرٌ هَلُمَّ إِلَيْهِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏هَذَا رَجُلٌ لَا ‏ ‏تُودَى عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَفَعَنِي مَالٌ قَطُّ إِلَّا مَالُ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ فَبَكَى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ وَهَلْ نَفَعَنِي اللَّهُ إِلَّا بِكَ وَهَلْ نَفَعَنِي اللَّهُ إِلَّا بِكَ وَهَلْ نَفَعَنِي اللَّهُ إِلَّا بِكَ ‏","","",""],[8436,8436,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَفْضَلُ وَأَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ الْمُؤْمِنِ الضَّعِيفِ وَفِي كُلٍّ خَيْرٌ احْرِصْ عَلَى مَا يَنْفَعُكَ وَلَا تَعْجَزْ فَإِنْ غَلَبَكَ أَمْرٌ فَقُلْ قَدَّرَ اللَّهُ وَمَا شَاءَ صَنَعَ وَإِيَّاكَ وَاللَّوَّ فَإِنَّ اللَّوَّ يُفْتَحُ مِنْ الشَّيْطَانِ ‏","","",""],[8437,8437,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدَعَنَّ النَّاسُ فَخْرَهُمْ فِي الْجَاهِلِيَّةِ أَوْ لَيَكُونَنَّ أَبْغَضَ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ الْخَنَافِسِ ‏","","",""],[8438,8438,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مِكْرَزٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏رَجُلٌ يُرِيدُ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَهُوَ يَبْتَغِي مِنْ عَرَضِ الدُّنْيَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَجْرَ لَهُ فَأَعْظَمَ النَّاسُ ذَلِكَ وَقَالُوا لِلرَّجُلِ عُدْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّهُ لَمْ يَفْقَهْ فَأَعَادَ ذَلِكَ عَلَيْهِ ثَلَاثَ مَرَّاتٍ كُلَّ ذَلِكَ يَقُولُ لَا أَجْرَ لَهُ ‏","","",""],[8439,8439,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْرَابِيٌّ أَعْجَبَهُ صِحَّتُهُ وَجَلَدُهُ قَالَ ‏ ‏فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَتَى أَحْسَسْتَ أُمَّ مِلْدَمٍ قَالَ وَأَيُّ شَيْءٍ أُمُّ مِلْدَمٍ قَالَ الْحُمَّى قَالَ وَأَيُّ شَيْءٍ الْحُمَّى قَالَ سَخَنَةٌ تَكُونُ بَيْنَ الْجِلْدِ وَالْعِظَامِ قَالَ مَا بِذَلِكَ لِي عَهْدٌ قَالَ فَمَتَى أَحْسَسْتَ بِالصُّدَاعِ قَالَ وَأَيُّ ‏ ‏شَيْءٍ الصُّدَاعُ قَالَ ضَرَبَانٌ يَكُونُ فِي الصُّدْغَيْنِ وَالرَّأْسِ قَالَ مَا لِي بِذَلِكَ عَهْدٌ قَالَ فَلَمَّا ‏ ‏قَفَّا ‏ ‏أَوْ ‏ ‏وَلَّى ‏ ‏الْأَعْرَابِيُّ قَالَ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ النَّارِ فَلْيَنْظُرْ إِلَيْهِ ‏","","",""],[8440,8440,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْوَةُ الْمَظْلُومِ مُسْتَجَابَةٌ وَإِنْ كَانَ فَاجِرًا فَفُجُورُهُ عَلَى نَفْسِهِ ‏","","",""],[8441,8441,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا مَا فِي الْبُيُوتِ مِنْ النِّسَاءِ وَالذُّرِّيَّةِ ‏ ‏لَأَقَمْتُ الصَّلَاةَ ‏ ‏صَلَاةَ الْعِشَاءِ وَأَمَرْتُ فِتْيَانِي يُحْرِقُونَ مَا فِي الْبُيُوتِ بِالنَّارِ ‏","","",""],[8442,8442,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أُحِبُّ أَنَّ عِنْدِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا وَيَمُرُّ بِي ثَلَاثٌ وَعِنْدِي مِنْهُ دِينَارٌ إِلَّا شَيْئًا أَعْدَدْتُهُ ‏ ‏لِغَرِيمِي ‏","","",""],[8443,8443,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ صُفُوفِ الرِّجَالِ أَوَّلُهَا وَشَرُّهَا آخِرُهَا وَخَيْرُ صُفُوفِ النِّسَاءِ آخِرُهَا وَشَرُّهَا أَوَّلُهَا ‏","","",""],[8444,8444,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ ‏ ‏يَرْضَى لَكُمْ ثَلَاثًا وَيَسْخَطُ لَكُمْ ثَلَاثًا ‏ ‏يَرْضَى لَكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا وَأَنْ تُنَاصِحُوا مَنْ وَلَّاهُ اللَّهُ أَمْرَكُمْ وَيَسْخَطُ لَكُمْ قِيلَ وَقَالَ وَإِضَاعَةَ الْمَالِ وَكَثْرَةَ السُّؤَالِ ‏","","",""],[8445,8445,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَغْطِيَةِ الْوَضُوءِ ‏ ‏وَإِيكَاءِ ‏ ‏السِّقَاءِ ‏ ‏وَإِكْفَاءِ ‏ ‏الْإِنَاءِ ‏","","",""],[8446,8446,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَعْرِفَنَّ أَحَدًا مِنْكُمْ أَتَاهُ عَنِّي حَدِيثٌ وَهُوَ مُتَّكِئٌ فِي ‏ ‏أَرِيكَتِهِ ‏ ‏فَيَقُولُ اتْلُوا عَلَيَّ بِهِ قُرْآنًا مَا جَاءَكُمْ عَنِّي مِنْ خَيْرٍ قُلْتُهُ أَوْ لَمْ أَقُلْهُ فَأَنَا أَقُولُهُ وَمَا أَتَاكُمْ عَنِّي مِنْ شَرٍّ فَأَنَا لَا أَقُولُ الشَّرَّ ‏","","",""],[8447,8447,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَأُرَاهُ ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ يَرْفَعُونَ أَبْصَارَهُمْ فِي الصَّلَاةِ إِلَى السَّمَاءِ أَوْ لَيَخْطِفَنَّ اللَّهُ أَبْصَارَهُمْ ‏","","",""],[8448,8448,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏مَوْلَى ‏ ‏التَّوْأَمَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَلَسَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ أَنْتَ قَالَ بَرْبَرِيٌّ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُمْ عَنِّي قَالَ بِمِرْفَقِهِ ‏ ‏هَكَذَا ‏ ‏فَلَمَّا قَامَ عَنْهُ أَقْبَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ الْإِيمَانَ لَا ‏ ‏يُجَاوِزُ ‏ ‏حَنَاجِرَهُمْ ‏","","",""],[8449,8449,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتَّخِذُوا قَبْرِي عِيدًا وَلَا تَجْعَلُوا بُيُوتَكُمْ قُبُورًا وَحَيْثُمَا كُنْتُمْ فَصَلُّوا عَلَيَّ فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي ‏","","",""],[8450,8450,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَأْخُذَ أُمَّتِي بِمَأْخَذِ الْأُمَمِ وَالْقُرُونِ قَبْلَهَا شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ كَمَا فَعَلَتْ ‏ ‏فَارِسُ ‏ ‏وَالرُّومُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَلْ النَّاسُ إِلَّا أُولَئِكَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏يَعْنِي ‏ ‏مِثْلَهُ ‏","","",""],[8451,8451,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ صَدَاقُنَا إِذْ كَانَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ ‏ ‏أَوَاقٍ ‏ ‏وَطَبَّقَ ‏ ‏بِيَدَيْهِ وَذَلِكَ أَرْبَعُ مِائَةٍ ‏","","",""],[8452,8452,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي رَأَيْتُنِي عَلَى ‏ ‏قَلِيبٍ ‏ ‏أَنْزِعُ بِدَلْوٍ ثُمَّ أَخَذَهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ بِهَا ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏ذَنُوبَيْنِ ‏ ‏فِيهِمَا ضَعْفٌ وَاللَّهُ يَرْحَمُهُ ثُمَّ أَخَذَهَا ‏ ‏عُمَرُ ‏ ‏فَإِنْ بَرِحَ يَنْزِعُ حَتَّى اسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏ثُمَّ ضَرَبَتْ ‏ ‏بِعَطَنٍ ‏ ‏فَمَا رَأَيْتُ مِنْ نَزْعِ ‏ ‏عَبْقَرِيٍّ ‏ ‏أَحْسَنَ مِنْ نَزْعِ ‏ ‏عُمَرَ ‏","","",""],[8453,8453,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى عَلَى الْجِنَازَةِ قَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَ ذَكَرِنَا وَأُنْثَانَا اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلَامِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِيمَانِ ‏","","",""],[8454,8454,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّيْطَانَ قَدْ ‏ ‏أَيِسَ ‏ ‏أَنْ يُعْبَدَ بِأَرْضِكُمْ هَذِهِ وَلَكِنَّهُ قَدْ رَضِيَ مِنْكُمْ بِمَا ‏ ‏تَحْقِرُونَ ‏","","",""],[8455,8455,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَوْا مَا قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏مَا أَنْعَمْتُ عَلَى عِبَادِي مِنْ نِعْمَةٍ إِلَّا أَصْبَحَ فَرِيقٌ مِنْهُمْ كَافِرِينَ يَقُولُونَ الْكَوْكَبُ وَبِالْكَوْكَبِ ‏","","",""],[8456,8456,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ يَعْنِي الصَّنْعَانِيَّ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عَلَى نَاسٍ جُلُوسٍ فَقَالَ أَلَا أُخْبِرُكُمْ بِخَيْرِكُمْ مِنْ شَرِّكُمْ فَسَكَتَ الْقَوْمُ فَأَعَادَهَا ثَلَاثَ مَرَّاتٍ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏خَيْرُكُمْ مَنْ ‏ ‏يُرْجَى خَيْرُهُ وَيُؤْمَنُ شَرُّهُ وَشَرُّكُمْ مَنْ لَا ‏ ‏يُرْجَى خَيْرُهُ وَلَا يُؤْمَنُ شَرُّهُ ‏","","",""],[8457,8457,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقُولُ الْعَبْدُ مَالِي وَمَالِي وَإِنَّمَا لَهُ مِنْ مَالِهِ ثَلَاثٌ مَا أَكَلَ فَأَفْنَى أَوْ لَبِسَ فَأَبْلَى أَوْ أَعْطَى فَأَقْنَى مَا سِوَى ذَلِكَ فَهُوَ ذَاهِبٌ وَتَارِكُهُ لِلنَّاسِ ‏","","",""],[8458,8458,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقَعَنَّ رَجُلٌ عَلَى امْرَأَةٍ وَحَمْلُهَا لِغَيْرِهِ ‏","","",""],[8459,8459,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ إِنْسَانٍ تَلِدُهُ أُمُّهُ ‏ ‏يَلْكُزُهُ ‏ ‏الشَّيْطَانُ بِحِضْنَيْهِ إِلَّا مَا كَانَ مِنْ ‏ ‏مَرْيَمَ ‏ ‏وَابْنِهَا أَلَمْ تَرَوْا إِلَى الصَّبِيِّ حِينَ يَسْقُطُ كَيْفَ يَصْرُخُ قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ فَذَاكَ حِينَ ‏ ‏يَلْكُزُهُ ‏ ‏الشَّيْطَانُ بِحِضْنَيْهِ ‏","","",""],[8460,8460,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ الْكَافِرُ وَقَاتِلُهُ مِنْ الْمُسْلِمِينَ فِي النَّارِ أَبَدًا ‏","","",""],[8461,8461,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُجْمَعُ النَّاسُ يَوْمَ الْقِيَامَةِ فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ ثُمَّ يَطْلُعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ ثُمَّ يُقَالُ أَلَا تَتَّبِعُ كُلُّ أُمَّةٍ مَا كَانُوا يَعْبُدُونَ فَيَتَمَثَّلُ لِصَاحِبِ الصَّلِيبِ صَلِيبُهُ وَلِصَاحِبِ الصُّوَرِ صُوَرُهُ وَلِصَاحِبِ النَّارِ نَارُهُ فَيَتَّبِعُونَ مَا كَانُوا يَعْبُدُونَ وَيَبْقَى الْمُسْلِمُونَ فَيَطْلُعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ فَيَقُولُ أَلَا تَتَّبِعُونَ النَّاسَ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ اللَّهُ رَبُّنَا وَهَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ ثُمَّ ‏ ‏يَتَوَارَى ‏ ‏ثُمَّ يَطْلُعُ فَيَقُولُ أَلَا تَتَّبِعُونَ النَّاسَ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ نَعُوذُ بِاللَّهِ مِنْكَ اللَّهُ رَبُّنَا وَهَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ قَالُوا وَهَلْ ‏ ‏نَرَاهُ يَا رَسُولَ اللَّهِ قَالَ وَهَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ ‏ ‏الْبَدْرِ قَالُوا لَا قَالَ فَإِنَّكُمْ لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ تِلْكَ السَّاعَةَ ثُمَّ ‏ ‏يَتَوَارَى ‏ ‏ثُمَّ يَطْلُعُ فَيُعَرِّفُهُمْ نَفْسَهُ أَنَا رَبُّكُمْ فَيَقُولُ أَنَا رَبُّكُمْ اتَّبِعُونِي فَيَقُومُ الْمُسْلِمُونَ وَيُوضَعُ الصِّرَاطُ فَهُمْ عَلَيْهِ مِثْلُ جِيَادِ الْخَيْلِ وَالرِّكَابِ وَقَوْلُهُمْ عَلَيْهِ سَلِّمْ سَلِّمْ وَيَبْقَى أَهْلُ النَّارِ فَيُطْرَحُ مِنْهُمْ فِيهَا فَوْجٌ فَيُقَالُ هَلْ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ ثُمَّ يُطْرَحُ فِيهَا فَوْجٌ فَيُقَالُ هَلْ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ حَتَّى إِذَا ‏ ‏أُوعِبُوا ‏ ‏فِيهَا وَضَعَ الرَّحْمَنُ عَزَّ وَجَلَّ قَدَمَهُ فِيهَا ‏ ‏وَزَوَى ‏ ‏بَعْضَهَا إِلَى بَعْضٍ ثُمَّ قَالَتْ قَطْ قَطْ قَطْ وَإِذَا صُيِّرَ أَهْلُ الْجَنَّةِ فِي الْجَنَّةِ وَأَهْلُ النَّارِ فِي النَّارِ أُتِيَ بِالْمَوْتِ ‏ ‏مُلَبَّبًا ‏ ‏فَيُوقَفُ عَلَى السُّورِ الَّذِي بَيْنَ أَهْلِ النَّارِ وَأَهْلِ الْجَنَّةِ ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ فَيَطَّلِعُونَ خَائِفِينَ ثُمَّ يُقَالُ يَا أَهْلَ النَّارِ فَيَطَّلِعُونَ مُسْتَبْشِرِينَ يَرْجُونَ ‏ ‏الشَّفَاعَةَ ‏ ‏فَيُقَالُ لِأَهْلِ الْجَنَّةِ وَلِأَهْلِ النَّارِ تَعْرِفُونَ هَذَا فَيَقُولُونَ هَؤُلَاءِ وَهَؤُلَاءِ قَدْ عَرَفْنَاهُ هُوَ الْمَوْتُ الَّذِي وُكِّلَ بِنَا فَيُضْجَعُ فَيُذْبَحُ ذَبْحًا عَلَى السُّورِ ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَأُزْوِيَ ‏ ‏بَعْضُهَا إِلَى بَعْضٍ ثُمَّ قَالَ قَطْ قَالَتْ قَطْ قَطْ ‏","","",""],[8462,8462,"","","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَفَّارَةُ الْمَجَالِسِ أَنْ يَقُولَ الْعَبْدُ سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ ‏","","",""],[8463,8463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يَقُولُ أَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[8464,8464,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏يَقْرَأُ فَقَالَ ‏ ‏لَقَدْ أُعْطِيَ هَذَا مِنْ مَزَامِيرِ آلِ ‏ ‏دَاوُدَ ‏ ‏النَّبِيِّ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[8465,8465,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْبَرَاءُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِأَهْلِ الْجَنَّةِ هُمْ الضُّعَفَاءُ وَالْمَظْلُومُونَ أَلَا أُنَبِّئُكُمْ بِأَهْلِ النَّارِ كُلُّ شَدِيدٍ ‏ ‏جَعْظَرِيٍّ ‏","","",""],[8466,8466,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْبَرَاءُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِشِرَارِكُمْ فَقَالَ هُمْ الثَّرْثَارُونَ الْمُتَشَدِّقُونَ أَلَا أُنَبِّئُكُمْ بِخِيَارِكُمْ أَحَاسِنُكُمْ أَخْلَاقًا ‏","","",""],[8467,8467,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏الْبَرَاءُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏خَلِيلِي ‏ ‏الصَّادِقُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَكُونُ فِي هَذِهِ الْأُمَّةِ بَعْثٌ إِلَى ‏ ‏السِّنْدِ ‏ ‏وَالْهِنْدِ ‏ ‏فَإِنْ أَنَا أَدْرَكْتُهُ فَاسْتُشْهِدْتُ فَذَلِكَ وَإِنْ أَنَا ‏ ‏فَذَكَرَ كَلِمَةً رَجَعْتُ وَأَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏الْمُحَرَّرُ ‏ ‏قَدْ أَعْتَقَنِي مِنْ النَّارِ ‏","","",""],[8468,8468,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتَقُومَنَّ ‏ ‏السَّاعَةُ وَثَوْبُهُمَا بَيْنَهُمَا لَا يَطْوِيَانِهِ وَلَا يَتَبَايَعَانِهِ وَلَتَقُومَنَّ السَّاعَةُ وَقَدْ حَلَبَ ‏ ‏لِقْحَتَهُ ‏ ‏لَا يَطْعَمُهُ وَلَتَقُومَنَّ السَّاعَةُ وَقَدْ رَفَعَ لُقْمَتَهُ إِلَى ‏ ‏فِيهِ وَلَا يَطْعَمُهَا وَلَتَقُومَنَّ السَّاعَةُ وَالرَّجُلُ ‏ ‏يَلِيطُ ‏ ‏حَوْضَهُ لَا ‏ ‏يَسْقِي مِنْهُ ‏","","",""],[8469,8469,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَعْجَبُونَ كَيْفَ يُصْرَفُ عَنِّي شَتْمُ ‏ ‏قُرَيْشٍ ‏ ‏يَشْتِمُونَ ‏ ‏مُذَمَّمًا ‏ ‏وَأَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَيَلْعَنُونَ ‏ ‏مُذَمَّمًا ‏ ‏وَأَنَا ‏ ‏مُحَمَّدٌ ‏","","",""],[8470,8470,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏أَوْ ‏ ‏مُزَيْنَةُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏خَيْرٌ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ ‏ ‏أَسَدٍ ‏ ‏وطَيِّئٍ ‏ ‏وَغَطَفَانَ ‏","","",""],[8471,8471,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَدْخُلُ الْجَنَّةَ يَنْعَمُ لَا يَيْئَسُ وَلَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[8472,8472,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ مَرَّتْ سَحَابَةٌ فَقَالَ أَتَدْرُونَ مَا هَذِهِ قَالَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏الْعَنَانُ ‏ ‏وَرَوَايَا الْأَرْضِ يَسُوقُهُ اللَّهُ إِلَى مَنْ لَا يَشْكُرُهُ مِنْ عِبَادِهِ وَلَا يَدْعُونَهُ أَتَدْرُونَ مَا هَذِهِ فَوْقَكُمْ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏الرَّقِيعُ ‏ ‏مَوْجٌ ‏ ‏مَكْفُوفٌ ‏ ‏وَسَقْفٌ مَحْفُوظٌ أَتَدْرُونَ كَمْ بَيْنَكُمْ وَبَيْنَهَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَسِيرَةُ خَمْسِ مِائَةِ عَامٍ قَالَ أَتَدْرُونَ مَا الَّتِي فَوْقَهَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ سَمَاءٌ أُخْرَى أَتَدْرُونَ كَمْ بَيْنَكُمْ وَبَيْنَهَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَسِيرَةُ خَمْسِ مِائَةِ عَامٍ حَتَّى عَدَّ سَبْعَ سَمَاوَاتٍ ثُمَّ قَالَ أَتَدْرُونَ مَا فَوْقَ ذَلِكَ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ الْعَرْشُ قَالَ أَتَدْرُونَ كَمْ بَيْنَكُمْ وَبَيْنَ السَّمَاءِ السَّابِعَةِ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَسِيرَةُ خَمْسِ مِائَةِ عَامٍ ثُمَّ قَالَ أَتَدْرُونَ مَا هَذَا تَحْتَكُمْ قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ أَرْضٌ أَتَدْرُونَ مَا تَحْتَهَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ أَرْضٌ أُخْرَى أَتَدْرُونَ كَمْ بَيْنَهَا وَبَيْنَهَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ مَسِيرَةُ خَمْسِ مِائَةِ عَامٍ حَتَّى عَدَّ سَبْعَ أَرَضِينَ ثُمَّ قَالَ وَايْمُ اللَّهِ لَوْ دَلَّيْتُمْ أَحَدَكُمْ بِحَبْلٍ إِلَى الْأَرْضِ السُّفْلَى السَّابِعَةِ لَهَبَطَ ثُمَّ قَرَأَ ‏ { ‏هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ‏}","","",""],[8473,8473,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَقَدْ سَمِعْتُهُ مِنْ ‏ ‏رَبِيعَةَ ‏ ‏فَلَمْ أُنْكِرْ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ ‏ ‏أَوْ أَفْضَلُ ‏ ‏وَأَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ الْمُؤْمِنِ الضَّعِيفِ وَكُلٌّ خَيْرٌ احْرِصْ عَلَى مَا يَنْفَعُكَ وَلَا تَعْجِزْ فَإِنْ غَلَبَكَ أَمْرٌ فَقُلْ قَدَّرَ اللَّهُ وَمَا شَاءَ صَنَعَ وَإِيَّاكَ وَاللَّوَّ فَإِنَّ اللَّوَّ يُفْتَحُ مِنْ الشَّيْطَانِ ‏","","",""],[8474,8474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏بَرَكَةَ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ فِي الدُّعَاءِ حَتَّى أَرَى بَيَاضَ إِبْطَيْهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهُوَ ‏ ‏أَبُو الْمُعْتَمِرِ ‏ ‏لَا أَظُنُّهُ إِلَّا فِي ‏ ‏الِاسْتِسْقَاءِ ‏","","",""],[8475,8475,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏نُعَيْمُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو جَهْلٍ ‏ ‏هَلْ يُعَفِّرُ ‏ ‏مُحَمَّدٌ ‏ ‏وَجْهَهُ بَيْنَ أَظْهُرِكُمْ قَالَ فَقِيلَ نَعَمْ فَقَالَ ‏ ‏وَاللَّاتِ ‏ ‏وَالْعُزَّى ‏ ‏يَمِينًا يَحْلِفُ بِهَا لَئِنْ رَأَيْتُهُ يَفْعَلُ ذَلِكَ ‏ ‏لَأَطَأَنَّ ‏ ‏عَلَى رَقَبَتِهِ أَوْ لَأُعَفِّرَنَّ وَجْهَهُ فِي التُّرَابِ قَالَ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي زَعَمَ ‏ ‏لَيَطَأُ ‏ ‏عَلَى رَقَبَتِهِ قَالَ فَمَا فَجَأَهُمْ مِنْهُ إِلَّا وَهُوَ يَنْكُصُ عَلَى عَقِبَيْهِ ‏ ‏وَيَتَّقِي بِيَدَيْهِ قَالَ قَالُوا لَهُ مَا لَكَ قَالَ إِنَّ بَيْنِي وَبَيْنَهُ لَخَنْدَقًا مِنْ نَارٍ وَهَؤُلَاءِ أَجْنِحَةٌ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ دَنَا مِنِّي لَخَطَفَتْهُ الْمَلَائِكَةُ عُضْوًا عُضْوًا ‏ ‏قَالَ ‏ ‏فَأُنْزِلَ لَا أَدْرِي فِي حَدِيثِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ شَيْءٍ بَلَغَهُ ‏ { ‏إِنَّ الْإِنْسَانَ ‏ ‏لَيَطْغَى أَنَّ رَآهُ اسْتَغْنَى ‏} { ‏أَرَأَيْتَ الَّذِي يَنْهَى عَبْدًا إِذَا صَلَّى أَرَأَيْتَ إِنْ كَانَ عَلَى الْهُدَى أَوْ أَمَرَ بِالتَّقْوَى أَرَأَيْتَ إِنْ كَذَّبَ وَتَوَلَّى ‏} ‏يَعْنِي ‏ ‏أَبَا جَهْلٍ ‏ { ‏أَلَمْ يَعْلَمْ بِأَنَّ اللَّهَ يَرَى كَلَّا لَئِنْ لَمْ يَنْتَهِ ‏ ‏لَنَسْفَعًا ‏ ‏بِالنَّاصِيَةِ ‏ ‏نَاصِيَةٍ ‏ ‏كَاذِبَةٍ خَاطِئَةٍ فَلْيَدْعُ نَادِيَهُ ‏} ‏قَالَ يَدْعُو قَوْمَهُ ‏ { ‏سَنَدْعُ ‏ ‏الزَّبَانِيَةَ ‏ } ‏قَالَ ‏ ‏يَعْنِي الْمَلَائِكَةَ ‏ { ‏كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ ‏}","","",""],[8476,8476,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ يَوْمَ الْقِيَامَةِ ‏ ‏أَيْنَ الْمُتَحَابُّونَ بِجَلَالِي ‏ ‏الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي ‏","","",""],[8477,8477,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَعُودَ أَرْضُ ‏ ‏الْعَرَبِ ‏ ‏مُرُوجًا ‏ ‏وَأَنْهَارًا وَحَتَّى ‏ ‏يَسِيرَ الرَّاكِبُ بَيْنَ ‏ ‏الْعِرَاقِ ‏ ‏وَمَكَّةَ ‏ ‏لَا يَخَافُ إِلَّا ضَلَالَ الطَّرِيقِ وَحَتَّى يَكْثُرَ الْهَرْجُ قَالُوا وَمَا الْهَرْجُ يَا رَسُولَ اللَّهِ قَالَ الْقَتْلُ ‏","","",""],[8478,8478,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَبَّحَ اللَّهَ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ وَحَمِدَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ وَكَبَّرَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ فَتِلْكَ تِسْعٌ وَتِسْعُونَ ثُمَّ قَالَ تَمَامُ الْمِائَةِ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ غُفِرَ لَهُ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[8479,8479,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ ‏","","",""],[8480,8480,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ الْحَكَمِ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ يُصْبِحُ وَحِينَ يُمْسِي سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ لَمْ يَأْتِ أَحَدٌ يَوْمَ الْقِيَامَةِ بِأَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا أَحَدٌ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَيْهِ ‏","","",""],[8481,8481,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ الْحَكَمِ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏بَدَا ‏ ‏جَفَا ‏ ‏وَمَنْ اتَّبَعَ الصَّيْدَ غَفَلَ وَمَنْ أَتَى أَبْوَابَ السُّلْطَانِ افْتُتِنَ وَمَا ازْدَادَ عَبْدٌ مِنْ السُّلْطَانِ قُرْبًا إِلَّا ازْدَادَ مِنْ اللَّهِ بُعْدًا ‏","","",""],[8482,8482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ يَعْنِي أَبَا أَحْمَدَ الزُّبَيْرِيَّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمِّي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ أَحَدُكُمْ مَا لَهُ فِي أَنْ يَمْشِيَ بَيْنَ يَدَيْ أَخِيهِ مُعْتَرِضًا وَهُوَ يُنَاجِي رَبَّهُ كَانَ أَنْ يَقِفَ فِي ذَلِكَ الْمَكَانِ مِائَةَ عَامٍ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَخْطُوَ ‏","","",""],[8483,8483,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنِ ‏ ‏الْحُصَيْنِ ‏ ‏كَذَا ‏ ‏قَالَ عَنْ ‏ ‏أَبِي سَعْدِ الْخَيْرِ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اكْتَحَلَ ‏ ‏فَلْيُوتِرْ ‏ ‏وَمَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ عَلَيْهِ وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏ ‏وَمَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ وَمَنْ أَكَلَ فَمَا ‏ ‏تَخَلَّلَ ‏ ‏فَلْيَلْفِظْ ‏ ‏وَمَنْ ‏ ‏لَاكَ ‏ ‏بِلِسَانِهِ فَلْيَبْتَلِعْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ وَمَنْ أَتَى ‏ ‏الْغَائِطَ ‏ ‏فَلْيَسْتَتِرْ فَإِنْ لَمْ يَجِدْ إِلَّا أَنْ يَجْمَعَ ‏ ‏كَثِيبًا ‏ ‏فَلْيَسْتَدْبِرْهُ ‏ ‏فَإِنَّ الشَّيْطَانَ يَلْعَبُ بِمَقَاعِدِ بَنِي ‏ ‏آدَمَ ‏ ‏مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لَا فَلَا حَرَجَ ‏","","",""],[8484,8484,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَلَفٌ يَعْنِي ابْنَ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَسَمِعْنَا ‏ ‏وَجْبَةً ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَا هَذَا قُلْنَا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏هَذَا حَجَرٌ أُرْسِلَ فِي جَهَنَّمَ مُنْذُ سَبْعِينَ خَرِيفًا فَالْآنَ انْتَهَى إِلَى قَعْرِهَا ‏","","",""],[8485,8485,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَلَفٌ يَعْنِي ابْنَ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏قَالَ ‏ ‏كُنْتُ خَلْفَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يَتَوَضَّأُ وَهُوَ يُمِرُّ الْوَضُوءَ إِلَى إِبْطِهِ فَقُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مَا هَذَا الْوُضُوءُ قَالَ يَا ‏ ‏بَنِي فَرُّوخَ ‏ ‏أَنْتُمْ هَاهُنَا لَوْ عَلِمْتُ أَنَّكُمْ هَاهُنَا مَا تَوَضَّأْتُ هَذَا الْوُضُوءَ إِنِّي سَمِعْتُ ‏ ‏خَلِيلِي ‏ ‏يَقُولُ ‏ ‏تَبْلُغُ ‏ ‏الْحِلْيَةُ ‏ ‏مِنْ الْمُؤْمِنِ إِلَى حَيْثُ يَبْلُغُ الْوُضُوءُ ‏","","",""],[8486,8486,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَبِي مَاتَ وَتَرَكَ مَالًا وَلَمْ يُوصِ فَهَلْ يُكَفِّرُ عَنْهُ أَنْ أَتَصَدَّقَ عَنْهُ فَقَالَ نَعَمْ ‏","","",""],[8487,8487,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَدْرُونَ مَنْ الْمُفْلِسُ قَالُوا الْمُفْلِسُ فِينَا مَنْ لَا دِرْهَمَ لَهُ وَلَا مَتَاعَ قَالَ ‏ ‏إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلَاةٍ وَصِيَامٍ وَزَكَاةٍ ‏ ‏وَيَأْتِي قَدْ شَتَمَ هَذَا ‏ ‏وَقَذَفَ ‏ ‏هَذَا وَأَكَلَ مَالَ هَذَا وَسَفَكَ دَمَ هَذَا وَضَرَبَ هَذَا ‏ ‏فَيُقْضَى هَذَا مِنْ حَسَنَاتِهِ وَهَذَا مِنْ حَسَنَاتِهِ فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يَقْضِيَ مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ ثُمَّ طُرِحَ فِي النَّارِ ‏","","",""],[8488,8488,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنَانِ تَزْنِيَانِ وَاللِّسَانُ يَزْنِي وَالْيَدَانِ يَزْنِيَانِ وَالرِّجْلَانِ يَزْنِيَانِ يُحَقِّقُ ذَلِكَ الْفَرْجُ أَوْ يُكَذِّبُهُ ‏","","",""],[8489,8489,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنْبَأَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ إِلَّا مِنْ ‏ ‏صَدَقَةٍ ‏ ‏جَارِيَةٍ أَوْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ ‏","","",""],[8490,8490,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ سِتٌّ قِيلَ مَا هِيَ يَا رَسُولَ اللَّهِ قَالَ إِذَا لَقِيتَهُ فَسَلِّمْ عَلَيْهِ وَإِذَا دَعَاكَ فَأَجِبْهُ وَإِذَا اسْتَنْصَحَكَ فَانْصَحْ لَهُ وَإِذَا عَطَسَ فَحَمِدَ اللَّهَ ‏ ‏فَشَمِّتْهُ ‏ ‏وَإِذَا مَرِضَ ‏ ‏فَعُدْهُ ‏ ‏وَإِذَا مَاتَ فَاتْبَعْهُ ‏","","",""],[8491,8491,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْكُفْرُ قِبَلَ الْمَشْرِقِ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ الْغَنَمِ وَالْفَخْرُ ‏ ‏وَالرِّيَاءُ ‏ ‏فِي ‏ ‏الْفَدَّادِينَ ‏ ‏وَالْخَيْلُ وَالْوَبَرُ ‏","","",""],[8492,8492,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَتُؤَدُّنَّ الْحُقُوقُ إِلَى أَهْلِهَا يَوْمَ الْقِيَامَةِ حَتَّى ‏ ‏تُقَادَ ‏ ‏الشَّاةُ ‏ ‏الْجَلْحَاءُ ‏ ‏مِنْ الشَّاةِ ‏ ‏الْقَرْنَاءِ ‏","","",""],[8493,8493,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏فِتَنًا ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ بِعَرَضٍ مِنْ الدُّنْيَا ‏","","",""],[8494,8494,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أبي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا ‏ ‏بِالْأَعْمَالِ سِتًّا طُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالَ ‏ ‏وَالدُّخَانَ وَالدَّابَّةَ أَوْ ‏ ‏خَاصَّةَ ‏ ‏أَحَدِكُمْ أَوْ أَمْرَ الْعَامَّةِ ‏","","",""],[8495,8495,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَإِذَا طَلَعَتْ آمَنَ النَّاسُ حِينَئِذٍ أَجْمَعُونَ وَيَوْمَئِذٍ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏}","","",""],[8496,8496,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَرَسُ مَزَامِيرُ الشَّيْطَانِ ‏","","",""],[8497,8497,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏سَعِّرْ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنَّمَا يَرْفَعُ اللَّهُ وَيَخْفِضُ إِنِّي لَأَرْجُو أَنْ أَلْقَى اللَّهَ عَزَّ وَجَلَّ وَلَيْسَ لِأَحَدٍ عِنْدِي مَظْلَمَةٌ قَالَ آخَرُ ‏ ‏سَعِّرْ ‏ ‏فَقَالَ ادْعُوا اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8498,8498,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اتَّقُوا اللَّعَّانَيْنِ قَالُوا وَمَا اللَّعَّانَانِ يَا رَسُولَ اللَّهِ قَالَ الَّذِي ‏ ‏يَتَخَلَّى ‏ ‏فِي طَرِيقِ النَّاسِ أَوْ فِي ظِلِّهِمْ ‏","","",""],[8499,8499,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَيَّ وَاحِدَةً صَلَّى اللَّهُ عَلَيْهِ عَشْرًا ‏","","",""],[8500,8500,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ ‏ ‏بَوَائِقَهُ ‏","","",""],[8501,8501,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُبَّ صَائِمٍ حَظُّهُ مِنْ صِيَامِهِ الْجُوعُ وَالْعَطَشُ وَرُبَّ قَائِمٍ حَظُّهُ مِنْ قِيَامِهِ السَّهَرُ ‏","","",""],[8502,8502,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ مِنْ خَيْرِ ‏ ‏قُرُونِ ‏ ‏بَنِي ‏ ‏آدَمَ ‏ ‏قَرْنًا ‏ ‏فَقَرْنًا ‏ ‏حَتَّى بُعِثْتُ مِنْ ‏ ‏الْقَرْنِ ‏ ‏الَّذِي كُنْتُ فِيهِ ‏","","",""],[8503,8503,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَسْعَدُ النَّاسِ بِشَفَاعَتِكَ يَوْمَ الْقِيَامَةِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ظَنَنْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَلَّا يَسْأَلَنِي عَنْ هَذَا الْحَدِيثِ أَحَدٌ أَوَّلَ مِنْكَ لِمَا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْحَدِيثِ ‏ ‏أَسْعَدُ النَّاسِ بِشَفَاعَتِي يَوْمَ الْقِيَامَةِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ خَالِصَةً مِنْ قِبَلِ نَفْسِهِ ‏","","",""],[8504,8504,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْرَكَ شَيْخًا يَمْشِي بَيْنَ ابْنَيْهِ ‏ ‏مُتَوَكِّئًا ‏ ‏عَلَيْهِمَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا شَأْنُ هَذَا الشَّيْخِ قَالَ ابْنَاهُ يَا رَسُولَ اللَّهِ كَانَ عَلَيْهِ ‏ ‏نَذْرٌ ‏ ‏فَقَالَ لَهُ ‏ ‏ارْكَبْ أَيُّهَا الشَّيْخُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ غَنِيٌّ عَنْكَ وَعَنْ ‏ ‏نَذْرِكَ ‏","","",""],[8505,8505,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يُقَرِّبُ مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏شَيْئًا لَمْ يَكُنْ اللَّهُ قَدَّرَهُ لَهُ وَلَكِنَّ ‏ ‏النَّذْرَ ‏ ‏مُوَافِقٌ الْقَدَرَ فَيُخْرَجُ بِذَلِكَ مِنْ الْبَخِيلِ مَا لَمْ يَكُنْ الْبَخِيلُ يُرِيدُ أَنْ يُخْرِجَ ‏","","",""],[8506,8506,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ دَعَا اللَّهُ ‏ ‏جِبْرِيلَ ‏ ‏فَأَرْسَلَهُ إِلَى الْجَنَّةِ فَقَالَ ‏ ‏انْظُرْ إِلَيْهَا وَمَا أَعْدَدْتُ لِأَهْلِهَا فَرَجَعَ إِلَيْهِ فَقَالَ وَعِزَّتِكَ لَا يَسْمَعُ بِهَا أَحَدٌ إِلَّا دَخَلَهَا فَحُجِبَتْ بِالْمَكَارِهِ فَقَالَ ارْجِعْ إِلَيْهَا فَانْظُرْ إِلَيْهَا فَرَجَعَ إِلَيْهَا فَقَالَ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَلَّا يَدْخُلَهَا أَحَدٌ ثُمَّ أَرْسَلَهُ إِلَى النَّارِ فَقَالَ اذْهَبْ فَانْظُرْ إِلَيْهَا وَمَا أَعْدَدْتُ لِأَهْلِهَا فِيهَا فَرَجَعَ إِلَيْهِ فَقَالَ وَعِزَّتِكَ لَا يَدْخُلُهَا أَحَدٌ يَسْمَعُ بِهَا فَحُجِبَتْ بِالشَّهَوَاتِ ثُمَّ قَالَ عُدْ إِلَيْهَا فَانْظُرْ إِلَيْهَا فَرَجَعَ إِلَيْهِ فَقَالَ وَعِزَّتِكَ لَقَدْ خَشِيتُ أَنْ لَا يَبْقَى أَحَدٌ إِلَّا دَخَلَهَا ‏","","",""],[8507,8507,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرٌو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصَرَفَ مِنْ الصُّبْحِ يَوْمًا فَأَتَى النِّسَاءَ فِي الْمَسْجِدِ فَوَقَفَ عَلَيْهِنَّ فَقَالَ يَا مَعْشَرَ النِّسَاءِ ‏ ‏مَا رَأَيْتُ مِنْ نَوَاقِصِ عُقُولٍ وَدِينٍ أَذْهَبَ لِقُلُوبِ ذَوِي الْأَلْبَابِ مِنْكُنَّ فَإِنِّي قَدْ رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ يَوْمَ الْقِيَامَةِ فَتَقَرَّبْنَ إِلَى اللَّهِ مَا اسْتَطَعْتُنَّ وَكَانَ فِي النِّسَاءِ امْرَأَةُ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَأَتَتْ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَأَخْبَرَتْهُ بِمَا سَمِعَتْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَخَذَتْ حُلِيًّا لَهَا فَقَالَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فَأَيْنَ تَذْهَبِينَ بِهَذَا الْحُلِيِّ فَقَالَتْ أَتَقَرَّبُ بِهِ إِلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ لَعَلَّ اللَّهَ أَنْ لَا يَجْعَلَنِي مِنْ أَهْلِ النَّارِ فَقَالَ وَيْلَكِ هَلُمِّي فَتَصَدَّقِي بِهِ عَلَيَّ وَعَلَى وَلَدِي فَإِنَّا لَهُ مَوْضِعٌ فَقَالَتْ لَا وَاللَّهِ حَتَّى أَذْهَبَ بِهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَهَبَتْ تَسْتَأْذِنُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ ‏ ‏زَيْنَبُ ‏ ‏تَسْتَأْذِنُ يَا رَسُولَ اللَّهِ فَقَالَ أَيُّ الزَّيَانِبِ هِيَ فَقَالُوا امْرَأَةُ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏فَقَالَ ائْذَنُوا لَهَا فَدَخَلَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي سَمِعْتُ مِنْكَ مَقَالَةً فَرَجَعْتُ إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَحَدَّثْتُهُ وَأَخَذْتُ حُلِيًّا أَتَقَرَّبُ بِهِ إِلَى اللَّهِ وَإِلَيْكَ رَجَاءَ أَنْ لَا يَجْعَلَنِي اللَّهُ مِنْ أَهْلِ النَّارِ فَقَالَ لِي ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏تَصَدَّقِي بِهِ عَلَيَّ وَعَلَى وَلَدِي فَإِنَّا لَهُ مَوْضِعٌ فَقُلْتُ حَتَّى أَسْتَأْذِنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَصَدَّقِي بِهِ عَلَيْهِ وَعَلَى بَنِيهِ فَإِنَّهُمْ لَهُ مَوْضِعٌ ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ أَرَأَيْتَ مَا سَمِعْتُ مِنْكَ حِينَ وَقَفْتَ عَلَيْنَا مَا رَأَيْتُ مِنْ نَوَاقِصِ عُقُولٍ قَطُّ وَلَا دِينٍ أَذْهَبَ بِقُلُوبِ ذَوِي الْأَلْبَابِ مِنْكُنَّ قَالَتْ يَا رَسُولَ اللَّهِ فَمَا نُقْصَانُ دِينِنَا وَعُقُولِنَا فَقَالَ أَمَّا مَا ذَكَرْتُ مِنْ نُقْصَانِ دِينِكُنَّ فَالْحَيْضَةُ الَّتِي تُصِيبُكُنَّ تَمْكُثُ إِحْدَاكُنَّ مَا شَاءَ اللَّهُ أَنْ تَمْكُثَ لَا تُصَلِّي وَلَا تَصُومُ فَذَلِكَ مِنْ نُقْصَانِ دِينِكُنَّ وَأَمَّا مَا ذَكَرْتُ مِنْ نُقْصَانِ عُقُولِكُنَّ فَشَهَادَتُكُنَّ إِنَّمَا شَهَادَةُ الْمَرْأَةِ نِصْفُ شَهَادَةٍ ‏","","",""],[8508,8508,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْبِضُ اللَّهُ الْأَرْضَ يَوْمَ الْقِيَامَةِ وَيَطْوِي السَّمَاءَ بِيَمِينِهِ ثُمَّ يَقُولُ أَنَا الْمَلِكُ أَيْنَ مُلُوكُ الْأَرْضِ ‏","","",""],[8509,8509,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي السَّمْحِ ‏ ‏عَنِ ‏ ‏ابْنِ حُجَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْحَمِيمَ ‏ ‏لَيُصَبُّ عَلَى رُءُوسِهِمْ فَيَنْفُذُ الْجُمْجُمَةَ حَتَّى ‏ ‏يَخْلُصَ ‏ ‏إِلَى جَوْفِهِ ‏ ‏فَيَسْلُتَ ‏ ‏مَا فِي جَوْفِهِ حَتَّى ‏ ‏يَمْرُقَ ‏ ‏مِنْ قَدَمَيْهِ ‏","","",""],[8510,8510,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏وُهَيْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ وَلَمْ يَغْزُ وَلَمْ يُحَدِّثْ نَفْسَهُ بِغَزْوٍ مَاتَ عَلَى شُعْبَةِ نِفَاقٍ ‏","","",""],[8511,8511,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ أَبِي سَعِيدٍ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدًا الْمَقْبُرِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏احْتَبَسَ ‏ ‏فَرَسًا فِي سَبِيلِ اللَّهِ إِيمَانًا بِاللَّهِ وَتَصْدِيقًا لِمَوْعُودِهِ كَانَ شِبَعُهُ ‏ ‏وَرِيُّهُ ‏ ‏وَبَوْلُهُ ‏ ‏وَرَوْثُهُ ‏ ‏حَسَنَاتٍ فِي مِيزَانِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[8512,8512,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ‏} ‏قَالَ أَتَدْرُونَ مَا أَخْبَارُهَا قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ فَإِنَّ أَخْبَارَهَا أَنْ تَشْهَدَ عَلَى كُلِّ عَبْدٍ وَأَمَةٍ بِمَا عَمِلَ عَلَى ظَهْرِهَا أَنْ تَقُولَ عَمِلْتَ عَلَيَّ كَذَا وَكَذَا يَوْمَ كَذَا وَكَذَا قَالَ فَهُوَ أَخْبَارُهَا ‏","","",""],[8513,8513,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عِيسَى الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏مَوْلَى الْمُنْبَعِثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَعَلَّمُوا مِنْ أَنْسَابِكُمْ مَا تَصِلُونَ بِهِ أَرْحَامَكُمْ ‏ ‏فَإِنَّ صِلَةَ الرَّحِمِ مَحَبَّةٌ فِي الْأَهْلِ ‏ ‏مَثْرَاةٌ ‏ ‏فِي الْمَالِ ‏ ‏مَنْسَأَةٌ ‏ ‏فِي ‏ ‏أَثَرِهِ ‏","","",""],[8514,8514,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنِ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْكَلِمَةُ الطَّيِّبَةُ ‏ ‏صَدَقَةٌ ‏ ‏وَكُلُّ خُطْوَةٍ ‏ ‏يَخْطُوهَا إِلَى الصَّلَاةِ ‏ ‏صَدَقَةٌ ‏","","",""],[8515,8515,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ تَمِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَظَلَّكُمْ شَهْرُكُمْ هَذَا ‏ ‏لَمَحْلُوفُ ‏ ‏رَسُولِ اللَّهِ مَا مَرَّ بِالْمُؤْمِنِينَ شَهْرٌ خَيْرٌ لَهُمْ مِنْهُ وَلَا بِالْمُنَافِقِينَ شَهْرٌ شَرٌّ لَهُمْ مِنْهُ إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَكْتُبُ أَجْرَهُ وَنَوَافِلَهُ مِنْ قَبْلِ أَنْ يُدْخِلَهُ وَيَكْتُبُ إِصْرَهُ وَشَقَاءَهُ مِنْ قَبْلِ أَنْ يُدْخِلَهُ وَذَلِكَ أَنَّ الْمُؤْمِنَ يُعِدُّ فِيهِ الْقُوَّةَ لِلْعِبَادَةِ مِنْ النَّفَقَةِ وَيُعِدُّ الْمُنَافِقُ اتِّبَاعَ غَفْلَةِ النَّاسِ وَاتِّبَاعَ عَوْرَاتِهِمْ فَهُوَ غُنْمٌ لِلْمُؤْمِنِ يَغْتَنِمُهُ الْفَاجِرُ ‏","","",""],[8516,8516,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجٍّ ‏ ‏أَوْ عُمْرَةٍ ‏ ‏فَاسْتَقْبَلَنَا ‏ ‏رِجْلٌ ‏ ‏مِنْ جَرَادٍ فَجَعَلْنَا نَضْرِبُهُنَّ بِسِيَاطِنَا وَعِصِيِّنَا فَنَقْتُلُهُنَّ فَسُقِطَ فِي أَيْدِينَا فَقُلْنَا مَا نَصْنَعُ وَنَحْنُ مُحْرِمُونَ فَسَأَلْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَا ‏ ‏بَأْسَ ‏","","",""],[8517,8517,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ ‏ ‏الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ ‏ ‏لَاسْتَهَمُوا ‏ ‏عَلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏","","",""],[8518,8518,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ مِائَةَ مَرَّةٍ كَانَتْ لَهُ عَدْلَ عَشَرَةِ رِقَابٍ وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ وَكَانَتْ لَهُ ‏ ‏حِرْزًا ‏ ‏مِنْ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ وَلَمْ يَأْتِ أَحَدٌ أَفْضَلَ مِمَّا جَاءَ بِهِ إِلَّا امْرُؤٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ وَمَنْ قَالَ فِي يَوْمٍ مِائَةَ مَرَّةٍ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ ‏ ‏زَبَدِ ‏ ‏الْبَحْرِ ‏","","",""],[8519,8519,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي وَهُوَ بِطَرِيقٍ إِذْ اشْتَدَّ عَلَيْهِ الْعَطَشُ فَوَجَدَ بِئْرًا فَنَزَلَ فِيهَا فَشَرِبَ ثُمَّ خَرَجَ فَإِذَا كَلْبٌ يَلْهَثُ يَأْكُلُ ‏ ‏الثَّرَى ‏ ‏مِنْ الْعَطَشِ فَقَالَ لَقَدْ بَلَغَ هَذَا الْكَلْبَ مِنْ الْعَطَشِ مِثْلُ الَّذِي بَلَغَنِي فَنَزَلَ الْبِئْرَ فَمَلَأَ خُفَّهُ مَاءً ثُمَّ أَمْسَكَهُ بِفِيهِ حَتَّى ‏ ‏رَقِيَ ‏ ‏بِهِ فَسَقَى الْكَلْبَ فَشَكَرَ اللَّهُ لَهُ فَغَفَرَ لَهُ قَالُوا يَا رَسُولَ اللَّهِ وَإِنَّ لَنَا فِي الْبَهَائِمِ لَأَجْرًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُلِّ ذَاتِ ‏ ‏كَبِدٍ ‏ ‏رَطْبَةٍ أَجْرٌ ‏","","",""],[8520,8520,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ رَفَعَ يَدَيْهِ ‏ ‏مَدًّا ‏","","",""],[8521,8521,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أَنْقَابِ ‏ ‏الْمَدِينَةِ ‏ ‏مَلَائِكَةٌ لَا يَدْخُلُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ ‏","","",""],[8522,8522,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَاهُنَا فَوَاللَّهِ مَا ‏ ‏يَخْفَى عَلَيَّ خُشُوعُكُمْ وَلَا رُكُوعُكُمْ إِنِّي لَأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏","","",""],[8523,8523,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمَقَابِرِ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ لَكُمْ لَاحِقُونَ ‏","","",""],[8524,8524,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَافَهُ ‏ ‏ضَيْفٌ ‏ ‏وَهُوَ كَافِرٌ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَاةٍ فَحُلِبَتْ فَشَرِبَ الْكَافِرُ حِلَابَهَا ثُمَّ أُخْرَى فَشَرِبَهُ ثُمَّ أُخْرَى فَشَرِبَهُ حَتَّى شَرِبَ حِلَابَ سَبْعِ شِيَاهٍ ثُمَّ إِنَّهُ أَصْبَحَ فَأَسْلَمَ فَأَمَرَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَاةٍ فَشَرِبَ حِلَابَهَا ثُمَّ أَمَرَ بِأُخْرَى فَلَمْ يَسْتَتِمَّهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُ ‏ ‏يَأْكُلُ ‏ ‏فِي مِعًى وَاحِدٍ وَالْكَافِرُ ‏ ‏يَأْكُلُ ‏ ‏فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[8525,8525,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَسْلَمَ ‏ ‏قَالَ لَمَّا نِمْتُ هَذِهِ اللَّيْلَةَ لَدَغَتْنِي عَقْرَبٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا ‏ ‏لَوْ قُلْتَ حِينَ أَمْسَيْتَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ يَضُرَّكَ ‏","","",""],[8526,8526,"","","‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ الدِّيلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْغَيْثِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَافِلُ الْيَتِيمِ لَهُ أَوْ لِغَيْرِهِ أَنَا وَهُوَ كَهَاتَيْنِ فِي الْجَنَّةِ إِذَا اتَّقَى اللَّهَ ‏ ‏وَأَشَارَ ‏ ‏مَالِكٌ ‏ ‏بِالسَّبَّابَةِ وَالْوُسْطَى ‏","","",""],[8527,8527,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَيَّ وَاحِدَةً ‏ ‏يُصَلِّي اللَّهُ عَلَيْهِ عَشْرَةً ‏","","",""],[8528,8528,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَدْرَكَ مِنْ الصَّلَاةِ رَكْعَةً فَقَدْ أَدْرَكَهَا كُلَّهَا ‏","","",""],[8529,8529,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏بَيْعِ الْغَرَرِ ‏ ‏وَعَنْ ‏ ‏بَيْعِ الْحَصَاةِ ‏","","",""],[8530,8530,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبٍ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَمِنْبَرِي عَلَى حَوْضِي ‏","","",""],[8531,8531,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا زَنَتْ أَمَةُ أَحَدِكُمْ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ فِي الرَّابِعَةِ فَلْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعَرٍ ‏ ‏أَوْ ضَفِيرٍ مِنْ شَعَرٍ ‏","","",""],[8532,8532,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَى لِسَانِي مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ جَاءَ بَنُو فُلَانٍ فَقَالَ مَا أَرَاكُمْ إِلَّا قَدْ خَرَجْتُمْ مِنْ ‏ ‏الْحَرَمِ ‏ ‏ثُمَّ نَظَرَ فَقَالَ بَلْ أَنْتُمْ فِيهِ بَلْ أَنْتُمْ فِيهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏ثُمَّ جَاءَ ‏ ‏بَنُو جَارِيَةَ ‏ ‏وَإِنَّمَا هُمْ ‏ ‏بَنُو حَارِثَةَ ‏","","",""],[8533,8533,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏وَكَانَ نَازِلًا عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِالْمَدِينَةِ ‏ ‏قَالَ فَرَأَيْتُهُ ‏ ‏يُصَلِّي صَلَاةً لَيْسَتْ بِالْخَفِيفَةِ وَلَا بِالطَّوِيلَةِ قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏نَحْوًا مِنْ صَلَاةِ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏قَالَ فَقُلْتُ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏أَهَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ وَمَا أَنْكَرْتَ مِنْ صَلَاتِي قَالَ قُلْتُ خَيْرًا أَحْبَبْتُ أَنْ أَسْأَلَكَ قَالَ فَقُلْتُ نَعَمْ ‏ ‏أَوْ أَوْجَزَ ‏","","",""],[8534,8534,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ الصَّاغَانِيُّ مُحَمَّدُ بْنُ مُيَسَّرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَرَأَ فَأَنْصِتُوا وَإِذَا قَالَ ‏ { ‏وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏","","",""],[8535,8535,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ هَمَمْتُ أَنْ آمُرَ فِتْيَانِي فَيَجْمَعُوا حَطَبًا ثُمَّ آمُرَ رَجُلًا يَؤُمُّ النَّاسَ ثُمَّ ‏ ‏أُخَالِفُ ‏ ‏إِلَى رِجَالٍ يَتَخَلَّفُونَ عَنْ الصَّلَاةِ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ وَايْمُ اللَّهِ لَوْ يَعْلَمُ أَحَدُهُمْ أَنَّ لَهُ بِشُهُودِهَا ‏ ‏عَرْقًا ‏ ‏سَمِينًا أَوْ ‏ ‏مِرْمَاتَيْنِ ‏ ‏لَشَهِدَهَا وَلَوْ يَعْلَمُونَ مَا فِيهَا لَأَتَوْهَا وَلَوْ ‏ ‏حَبْوًا ‏","","",""],[8536,8536,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ ‏","","",""],[8537,8537,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْتَسِمُ وَرَثَتِي دِينَارًا مَا تَرَكْتُهُ بَعْدَ نَفَقَةِ نِسَائِي وَمَئُونَةِ عَامِلِي ‏ ‏يَعْنِي عَامِلَ أَرْضِهِ ‏ ‏فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[8538,8538,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْزِي وَلَدٌ وَالِدَهُ إِلَّا أَنْ يَجِدَهُ مَمْلُوكًا فَيَشْتَرِيَهُ فَيُعْتِقَهُ ‏","","",""],[8539,8539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغْرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَالَ اللَّهُ ‏ ‏الْكِبْرِيَاءُ رِدَائِي وَالْعَظَمَةُ ‏ ‏إِزَارِي ‏ ‏فَمَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا أَدْخَلْتُهُ جَهَنَّمَ ‏","","",""],[8540,8540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏لَا يَزْنِي الزَّانِي وَهُوَ مُؤْمِنٌ وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُ وَهُوَ مُؤْمِنٌ وَالتَّوْبَةُ مَعْرُوضَةٌ بَعْدُ ‏","","",""],[8541,8541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَطْلُ ‏ ‏ظُلْمُ الْغَنِيِّ وَمَنْ ‏ ‏أُتْبِعَ ‏ ‏عَلَى مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[8542,8542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ ‏ ‏يَتَقَاضَى ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوا لَهُ مِثْلَ سِنِّ بَعِيرِهِ قَالَ فَالْتَمَسُوا لَهُ فَلَمْ يَجِدُوا إِلَّا فَوْقَ سِنِّ بَعِيرِهِ قَالَ فَأَعْطُوهُ فَوْقَ بَعِيرِهِ فَقَالَ الْأَعْرَابِيُّ أَوْفَيْتَنِي أَوْفَاكَ اللَّهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خَيْرَكُمْ خَيْرُكُمْ قَضَاءً ‏","","",""],[8543,8543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً ‏","","",""],[8544,8544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي نَعْلَيْهِ ‏","","",""],[8545,8545,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْرِدُوا ‏ ‏بِالظُّهْرِ فَإِنَّ حَرَّهَا مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[8546,8546,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي عَامِرٍ ‏ ‏قَالَ ‏ ‏لِمَرْوَانَ ‏ ‏هَذَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَلَى الْبَابِ قَالَ ائْذَنُوا لَهُ قَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَوْشَكَ ‏ ‏الرَّجُلُ أَنْ يَتَمَنَّى أَنَّهُ ‏ ‏خَرَّ ‏ ‏مِنْ ‏ ‏الثُّرَيَّا ‏ ‏وَأَنَّهُ لَمْ ‏ ‏يَتَوَلَّ ‏ ‏أَوْ ‏ ‏يَلِ ‏ ‏شَكَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏مِنْ أَمْرِ النَّاسِ شَيْئًا ‏","","",""],[8547,8547,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ هَلَاكَ ‏ ‏الْعَرَبِ ‏ ‏بِيَدَيْ فِتْيَةٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ قَالَ ‏ ‏مَرْوَانُ ‏ ‏بِئْسَ وَاللَّهِ الْفِتْيَةُ هَؤُلَاءِ ‏","","",""],[8548,8548,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏قَالَ قِيلَ يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَظَلُّ عِنْدَ رَبِّي يُطْعِمُنِي وَيَسْقِينِي ‏","","",""],[8549,8549,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمَسْجِدِ فَرَآهُمْ ‏ ‏عِزِينَ ‏ ‏مُتَفَرِّقِينَ قَالَ فَغَضِبَ غَضَبًا شَدِيدًا مَا رَأَيْنَاهُ غَضِبَ غَضَبًا أَشَدَّ مِنْهُ قَالَ وَاللَّهِ ‏ ‏لَقَدْ هَمَمْتُ أَنْ آمُرَ رَجُلًا يَؤُمُّ النَّاسَ ثُمَّ أَتَتَبَّعَ هَؤُلَاءِ الَّذِينَ يَتَخَلَّفُونَ عَنْ الصَّلَاةِ فِي دُورِهِمْ فَأُحَرِّقَهَا عَلَيْهِمْ ‏ ‏وَرُبَّمَا قَالَ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ صَلَاةَ الْعِشَاءِ ‏","","",""],[8550,8550,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ ‏ ‏إِلَّا بِحَقِّهَا ‏ ‏وَحِسَابُهُمْ عَلَى اللَّهِ ‏","","",""],[8551,8551,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اثْنَانِ هُمَا كُفْرٌ ‏ ‏النِّيَاحَةُ ‏ ‏وَالطَّعْنُ ‏ ‏فِي النَّسَبِ ‏","","",""],[8552,8552,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُؤْتَ بِالْمَوْتِ يَوْمَ الْقِيَامَةِ كَبْشًا ‏ ‏أَمْلَحَ ‏ ‏فَيُقَالُ يَا أَهْلَ الْجَنَّةِ تَعْرِفُونَ هَذَا فَيَطَّلِعُونَ خَائِفِينَ مُشْفِقِينَ قَالَ يَقُولُونَ نَعَمْ قَالَ ثُمَّ يُنَادَى أَهْلُ النَّارِ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ قَالَ فَيُذْبَحُ ثُمَّ يُقَالُ خُلُودٌ فِي الْجَنَّةِ وَخُلُودٌ فِي النَّارِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ زَادَ فِيهِ يُؤْتَى بِهِ عَلَى الصِّرَاطِ فَيُذْبَحُ ‏","","",""],[8553,8553,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏أَنْبَأَنَا ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏الصَّدَقَةَ ‏ ‏لَا تَحِلُّ لِغَنِيٍّ وَلَا لِذِي ‏ ‏مِرَّةٍ ‏ ‏سَوِيٍّ ‏","","",""],[8554,8554,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤَذِّنُ مُؤْتَمَنٌ وَالْإِمَامُ ضَامِنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[8555,8555,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَسِيدِ بْنِ أَبِي أَسِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عَبَّاسٍ ‏ ‏مَوْلَى ‏ ‏عَقِيلَةَ بِنْتِ طَلْقٍ الْغِفَارِيَّةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ أَنْ يُحَلِّقَ حَبِيبَهُ حَلْقَةً مِنْ نَارٍ فَلْيَجْعَلْ لَهُ حَلْقَةً مِنْ ذَهَبٍ وَمَنْ أَحَبَّ أَنْ يُطَوِّقَ حَبِيبَهُ طَوْقًا مِنْ نَارٍ فَلْيُطَوِّقْهُ طَوْقًا مِنْ ذَهَبٍ وَمَنْ أَحَبَّ أَنْ يُسَوِّرَ حَبِيبَهُ سِوَارًا مِنْ نَارٍ فَلْيُسَوِّرْهُ سِوَارًا مِنْ ذَهَبٍ وَلَكِنْ عَلَيْكُمْ بِالْفِضَّةِ فَالْعَبُوا بِهَا ‏","","",""],[8556,8556,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ نَادَى ‏ ‏مُنَادٍ ‏ ‏يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ فِيهِ وَيَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ فِيهِ ‏","","",""],[8557,8557,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏الْجُلَاحِ أَبِي كَثِيرٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةَ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَاسًا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّا نَبْعُدُ فِي الْبَحْرِ وَلَا نَحْمِلُ مِنْ الْمَاءِ إِلَّا ‏ ‏الْإِدَاوَةَ ‏ ‏وَالْإِدَاوَتَيْنِ لِأَنَّا لَا نَجِدُ الصَّيْدَ حَتَّى نَبْعُدَ ‏ ‏أَفَنَتَوَضَّأُ بِمَاءِ الْبَحْرِ قَالَ نَعَمْ فَإِنَّهُ الْحِلُّ مَيْتَتُهُ الطَّهُورُ مَاؤُهُ ‏","","",""],[8558,8558,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَوَّلُ مَنْ ‏ ‏يُدْعَى ‏ ‏يَوْمَ الْقِيَامَةِ ‏ ‏آدَمُ ‏ ‏فَيُقَالُ هَذَا أَبُوكُمْ ‏ ‏آدَمُ ‏ ‏فَيَقُولُ يَا رَبِّ لَبَّيْكَ وَسَعْدَيْكَ فَيَقُولُ لَهُ رَبُّنَا ‏ ‏أَخْرِجْ نَصِيبَ جَهَنَّمَ مِنْ ذُرِّيَّتِكَ فَيَقُولُ يَا رَبِّ وَكَمْ فَيَقُولُ مِنْ كُلِّ مِائَةٍ تِسْعَةً وَتِسْعِينَ فَقُلْنَا يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِذَا أُخِذَ مِنَّا مِنْ كُلِّ مِائَةٍ تِسْعَةٌ وَتِسْعُونَ فَمَاذَا ‏ ‏يَبْقَى مِنَّا قَالَ إِنَّ أُمَّتِي فِي الْأُمَمِ كَالشَّعْرَةِ الْبَيْضَاءِ فِي الثَّوْرِ الْأَسْوَدِ ‏","","",""],[8559,8559,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي سُهَيْلِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَهَلَّ ‏ ‏رَمَضَانُ غُلِّقَتْ أَبْوَابُ النَّارِ وَفُتِّحَتْ أَبْوَابُ الْجَنَّةِ ‏ ‏وَصُفِّدَتْ ‏ ‏الشَّيَاطِينُ ‏","","",""],[8560,8560,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ وَإِنَّ الْبَيْتَ الَّذِي يُقْرَأُ فِيهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏ ‏لَا يَدْخُلُهُ الشَّيْطَانُ ‏","","",""],[8561,8561,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي قَالَ لِنِسْوَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لَا يَمُوتُ لِإِحْدَاكُنَّ ثَلَاثَةٌ مِنْ الْوَلَدِ فَتَحْتَسِبُهُ إِلَّا دَخَلَتْ الْجَنَّةَ فَقَالَتْ امْرَأَةٌ مِنْهُنَّ أَوْ اثْنَانِ يَا رَسُولَ اللَّهِ قَالَ أَوْ اثْنَانِ ‏","","",""],[8562,8562,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى ‏ ‏أَنْقَابِ ‏ ‏الْمَدِينَةِ ‏ ‏مَلَائِكَةٌ لَا يَدْخُلُهَا الطَّاعُونُ وَلَا ‏ ‏الدَّجَّالُ ‏","","",""],[8563,8563,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَافَرْتُمْ فِي ‏ ‏الْخَصِيبِ ‏ ‏فَأَعْطُوا الْإِبِلَ حَظَّهَا مِنْ الْأَرْضِ وَإِذَا سَافَرْتُمْ فِي ‏ ‏السَّنَةِ ‏ ‏فَبَادِرُوا ‏ ‏نِقْيَهَا ‏ ‏وَإِذَا ‏ ‏عَرَّسْتُمْ ‏ ‏فَاجْتَنِبُوا الطُّرُقَ فَإِنَّهَا طُرُقُ الدَّوَابِّ وَمَأْوَى ‏ ‏الْهَوَامِّ ‏ ‏بِاللَّيْلِ ‏","","",""],[8564,8564,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ ثَلَاثٍ ‏","","",""],[8565,8565,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَفَ عَلَى نَاسٍ جُلُوسٍ فَقَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِكُمْ مِنْ شَرِّكُمْ قَالَ فَسَكَتُوا فَقَالَ ذَلِكَ ثَلَاثَ مَرَّاتٍ فَقَالَ رَجُلٌ يَا نَبِيَّ اللَّهِ أَخْبِرْنَا بِخَيْرِنَا مِنْ شَرِّنَا قَالَ خَيْرُكُمْ مَنْ ‏ ‏يُرْجَى خَيْرُهُ وَيُؤْمَنُ شَرُّهُ وَشَرُّكُمْ مَنْ لَا ‏ ‏يُرْجَى خَيْرُهُ وَلَا يُؤْمَنُ شَرُّهُ ‏","","",""],[8566,8566,"","","‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ الْكَافِرُ وَقَاتِلُهُ فِي النَّارِ أَبَدًا ‏","","",""],[8567,8567,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْعَبْدَ يَتَكَلَّمُ بِالْكَلِمَةِ يَزِلُّ بِهَا فِي النَّارِ أَبْعَدَ مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ‏","","",""],[8568,8568,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ النَّارُ جُزْءٌ مِنْ مِائَةِ جُزْءٍ مِنْ جَهَنَّمَ ‏","","",""],[8569,8569,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَرَأَيْتُمْ لَوْ أَنَّ نَهْرًا بِبَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ مَا تَقُولُونَ هَلْ يَبْقَى مِنْ ‏ ‏دَرَنِهِ ‏ ‏قَالُوا لَا ‏ ‏يَبْقَى مِنْ ‏ ‏دَرَنِهِ ‏ ‏شَيْءٌ قَالَ ذَاكَ ‏ ‏مَثَلُ الصَّلَوَاتِ الْخَمْسِ يَمْحُو اللَّهُ بِهَا الْخَطَايَا ‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْهَادِ ‏ ‏فَذَكَرَ مِثْلَهُ لَمْ يَقُلْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[8570,8570,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِيمَانُ أَرْبَعَةٌ وَسِتُّونَ بَابًا أَرْفَعُهَا وَأَعْلَاهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏وَأَدْنَاهَا ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ ‏","","",""],[8571,8571,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلنَّاسِ ‏ ‏أَحْسِنُوا صَلَاتَكُمْ فَإِنِّي أَرَاكُمْ مِنْ خَلْفِي كَمَا أَرَاكُمْ أَمَامِي ‏","","",""],[8572,8572,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُلْدَغُ مُؤْمِنٌ مِنْ جُحْرٍ وَاحِدٍ مَرَّتَيْنِ ‏","","",""],[8573,8573,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏وَالْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَبَقَ ‏ ‏دِرْهَمٌ دِرْهَمَيْنِ قَالُوا وَكَيْفَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ كَانَ لِرَجُلٍ دِرْهَمَانِ فَتَصَدَّقَ ‏ ‏بِأَحَدِهِمَا ‏ ‏فَانْطَلَقَ رَجُلٌ إِلَى ‏ ‏عُرْضِ ‏ ‏مَالِهِ فَأَخَذَ مِنْهُ ‏ ‏مِائَةَ ‏ ‏أَلْفِ دِرْهَمٍ فَتَصَدَّقَ بِهَا ‏","","",""],[8574,8574,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَنْ يَزَالَ عَلَى هَذَا الْأَمْرِ ‏ ‏عِصَابَةٌ ‏ ‏عَلَى الْحَقِّ لَا يَضُرُّهُمْ خِلَافُ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ عَزَّ وَجَلَّ وَهُمْ عَلَى ذَلِكَ ‏","","",""],[8575,8575,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُؤْمِنُ مَنْ آمَنَهُ النَّاسُ عَلَى دِمَائِهِمْ وَأَمْوَالِهِمْ ‏","","",""],[8576,8576,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَلَى كُلِّ نَفْسٍ مِنْ بَنِي ‏ ‏آدَمَ ‏ ‏كُتِبَ حَظُّهُ مِنْ الزِّنَا أَدْرَكَ ذَلِكَ لَا مَحَالَةَ فَالْعَيْنُ زِنَاهَا النَّظَرُ وَالْآذَانُ زِنَاهَا ‏ ‏الِاسْتِمَاعُ وَالْيَدُ زِنَاهَا الْبَطْشُ وَالرِّجْلُ زِنَاهَا الْمَشْيُ وَاللِّسَانُ زِنَاهُ الْكَلَامُ وَالْقَلْبُ ‏ ‏يَهْوَى ‏ ‏وَيَتَمَنَّى وَيُصَدِّقُ ذَلِكَ وَيُكَذِّبُهُ الْفَرْجُ ‏","","",""],[8577,8577,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَكُونُ ‏ ‏كَنْزُ ‏ ‏أَحَدِهِمْ يَوْمَ الْقِيَامَةِ ‏ ‏شُجَاعًا ‏ ‏أَقْرَعَ ذَا ‏ ‏زَبِيبَتَيْنِ ‏ ‏يَتْبَعُ صَاحِبَهُ وَهُوَ يَتَعَوَّذُ مِنْهُ وَلَا يَزَالُ يَتْبَعُهُ حَتَّى يُلْقِمَهُ أُصْبُعَهُ ‏","","",""],[8578,8578,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ فِي حُبِّ اثْنَتَيْنِ طُولِ الْحَيَاةِ وَكَثْرَةِ الْمَالِ ‏","","",""],[8579,8579,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ يَعْنِي الشَّافِعِيَّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏وَأَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُلَامَسَةِ ‏ ‏وَالْمُنَابَذَةِ ‏","","",""],[8580,8580,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدِّينَارُ بِالدِّينَارِ وَالدِّرْهَمُ بِالدِّرْهَمِ لَا فَضْلَ بَيْنَهُمَا ‏","","",""],[8581,8581,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا يَبِعْ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا تَلَقَّوْا السِّلَعَ وَقَالَ ‏ ‏مَطْلُ ‏ ‏الْغَنِيِّ ظُلْمٌ وَإِذَا ‏ ‏أُتْبِعَ ‏ ‏أَحَدُكُمْ عَلَى مَلِيءٍ ‏ ‏فَلْيَتْبَعْ ‏","","",""],[8582,8582,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏خَوْلَةَ بِنْتَ يَسَارٍ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّهُ لَيْسَ لِي إِلَّا ثَوْبٌ وَاحِدٌ وَأَنَا أَحِيضُ فِيهِ فَكَيْفَ أَصْنَعُ فَقَالَ ‏ ‏إِذَا طَهُرْتِ فَاغْسِلِيهِ ثُمَّ صَلِّي فِيهِ فَقَالَتْ فَإِنْ لَمْ يَخْرُجْ الدَّمُ قَالَ يَكْفِيكِ الْمَاءُ وَلَا يَضُرُّكِ أَثَرُهُ ‏","","",""],[8583,8583,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمُؤْمِنَ ‏ ‏لَيُنْضِي ‏ ‏شَيَاطِينَهُ كَمَا ‏ ‏يُنْضِي ‏ ‏أَحَدُكُمْ بَعِيرَهُ فِي السَّفَرِ ‏","","",""],[8584,8584,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَصْحَابَ الصُّوَرِ الَّذِينَ يَعْمَلُونَهَا يُعَذَّبُونَ بِهَا يَوْمَ الْقِيَامَةِ يُقَالُ لَهُمْ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[8585,8585,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ يَمَانٍ وَالْفِقْهُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ أَتَاكُمْ أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏فَهُمْ أَرَقُّ ‏ ‏أَفْئِدَةً ‏ ‏وَأَلْيَنُ قُلُوبًا وَالْكُفْرُ قِبَلَ الْمَشْرِقِ وَالْفَخْرُ ‏ ‏وَالْخُيَلَاءُ ‏ ‏فِي أَهْلِ الْخَيْلِ وَالْإِبِلِ ‏ ‏وَالْفَدَّادِينَ ‏ ‏أَهْلِ ‏ ‏الْوَبَرِ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ الْغَنَمِ ‏","","",""],[8586,8586,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ شَيْئًا أَحْسَنَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّ الشَّمْسَ ‏ ‏تَجْرِي فِي وَجْهِهِ وَمَا رَأَيْتُ أَحَدًا أَسْرَعَ فِي مَشْيِهِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّمَا الْأَرْضُ تُطْوَى لَهُ إِنَّا لَنُجْهِدُ أَنْفُسَنَا وَإِنَّهُ لَغَيْرُ ‏ ‏مُكْتَرِثٍ ‏","","",""],[8587,8587,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُفَّتْ الْجَنَّةُ بِالْمَكَارِهِ وَحُفَّتْ النَّارُ بِالشَّهَوَاتِ ‏","","",""],[8588,8588,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ ‏ ‏عَنْ ‏ ‏ابْنِ حُجَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَافِرُوا تَصِحُّوا وَاغْزُوا تَسْتَغْنُوا ‏","","",""],[8589,8589,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ فِي حُبِّ اثْنَيْنِ طُولِ الْحَيَاةِ وَكَثْرَةِ الْمَالِ ‏","","",""],[8590,8590,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏عَنْ ‏ ‏مُحْصِنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ وُضُوءَهُ ثُمَّ رَاحَ فَوَجَدَ النَّاسَ قَدْ صَلَّوْا أَعْطَاهُ اللَّهُ مِثْلَ أَجْرِ مَنْ صَلَّاهَا أَوْ حَضَرَهَا لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا ‏","","",""],[8591,8591,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا ضَيْفٍ نَزَلَ بِقَوْمٍ فَأَصْبَحَ الضَّيْفُ مَحْرُومًا فَلَهُ أَنْ يَأْخُذَ بِقَدْرِ ‏ ‏قِرَاهُ ‏ ‏وَلَا حَرَجَ عَلَيْهِ ‏","","",""],[8592,8592,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسَتَيْنِ وَعَنْ بَيْعَتَيْنِ فَأَمَّا اللُّبْسَتَانِ فَإِنَّهُ ‏ ‏يَلْتَحِفُ ‏ ‏فِي ثَوْبِهِ وَيُخْرِجُ ‏ ‏شِقَّهُ ‏ ‏أَوْ ‏ ‏يَحْتَبِي ‏ ‏بِثَوْبٍ وَاحِدٍ ‏ ‏فَيُفْضِي بِفَرْجِهِ ‏ ‏إِلَى السَّمَاءِ وَأَمَّا الْبَيْعَتَانِ ‏ ‏فَالْمُلَامَسَةُ ‏ ‏أَلْقِ إِلَيَّ وَأُلْقِ إِلَيْكَ وَأَلْقِ ‏ ‏الْحَجَرَ ‏","","",""],[8593,8593,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو زُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرَّتْ بِهِ جِنَازَةٌ سَأَلَهُمْ عَلَيْهِ دَيْنٌ فَإِنْ قَالُوا نَعَمْ قَالَ تَرَكَ وَفَاءً فَإِنْ قَالُوا نَعَمْ صَلَّى ‏ ‏عَلَيْهِ وَإِلَّا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ ‏","","",""],[8594,8594,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدٍ الزُّهْرِيُّ ‏ ‏وَكَانَ مِنْ ‏ ‏الْقَارَةِ ‏ ‏وَهُوَ حَلِيفٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏ابْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُمْ كَانُوا يَحْمِلُونَ ‏ ‏اللَّبِنَ ‏ ‏لِبِنَاءِ ‏ ‏الْمَسْجِدِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُمْ قَالَ فَاسْتَقْبَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَارِضٌ ‏ ‏لَبِنَةً ‏ ‏عَلَى بَطْنِهِ فَظَنَنْتُ أَنَّهَا قَدْ شُقَّتْ عَلَيْهِ قُلْتُ نَاوِلْنِيهَا يَا رَسُولَ اللَّهِ قَالَ خُذْ غَيْرَهَا يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَإِنَّهُ ‏ ‏لَا عَيْشَ إِلَّا عَيْشُ الْآخِرَةِ ‏","","",""],[8595,8595,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا بُعِثْتُ لِأُتَمِّمَ صَالِحَ الْأَخْلَاقِ ‏","","",""],[8596,8596,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَيْكَ السَّمْعَ وَالطَّاعَةَ فِي عُسْرِكَ وَيُسْرِكَ ‏ ‏وَمَنْشَطِكَ ‏ ‏وَمَكْرَهِكَ ‏ ‏وَأَثَرَةٍ عَلَيْكَ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏الطَّاعَةُ وَلَمْ يَقُلْ السَّمْعَ ‏","","",""],[8597,8597,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ نُمَيْلَةَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَسُئِلَ عَنْ أَكْلِ الْقُنْفُذِ فَتَلَا هَذِهِ الْآيَةَ ‏ { ‏قُلْ لَا أَجِدُ فِيمَا أُوحِيَ إِلَيَّ مُحَرَّمًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏ ‏فَقَالَ ‏ ‏شَيْخٌ ‏ ‏عِنْدَهُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏ذُكِرَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏خَبِيثٌ ‏ ‏مِنْ ‏ ‏الْخَبَائِثِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنْ كَانَ قَالَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُوَ كَمَا قَالَهُ ‏","","",""],[8598,8598,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ أَحَدُكُمْ فَلَا ‏ ‏يَبْرُكْ ‏ ‏كَمَا ‏ ‏يَبْرُكُ ‏ ‏الْجَمَلُ وَلْيَضَعْ يَدَيْهِ ثُمَّ رُكْبَتَيْهِ ‏","","",""],[8599,8599,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏رَفَّأَ ‏ ‏إِنْسَانًا قَالَ بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا عَلَى خَيْرٍ ‏","","",""],[8600,8600,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏رَفَّأَ ‏ ‏الْإِنْسَانَ إِذَا تَزَوَّجَ قَالَ بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ ‏","","",""]];
